use crate::*;
use crate::owned::{NativeRecordSchema,NativeSchemaLeaf,NativeRecordKey,NativeSchemaKeySource,NativeFieldMatch,NativeRecordMatcher};
use crate::owned::tree::{NativeValueSource,invalid};
use crate::{DslValue,Number,retained_clone::RetainedCloneSource};
fn nested_schema(index:usize)->Option<NativeRecordSchema>{match index{0=>Some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"dup",ordinal:0})),1=>Some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"beta",ordinal:1})),2=>Some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaz",ordinal:2})),_=>None}}
fn root_schema(index:usize)->Option<NativeRecordSchema>{match index{0=>Some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"alpha",ordinal:0})),1=>Some(NativeRecordSchema::Flatten{fields:nested_schema,count:3}),2=>Some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"dup",ordinal:2})),3=>Some(NativeRecordSchema::Union{fields:union_schema,count:2}),_=>None}}
fn union_schema(index:usize)->Option<NativeRecordSchema>{if index<2{Some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"union",ordinal:7}))}else{None}}
struct KeySource{name:String,ordinal:Option<u16>}
impl NativeValueSource for KeySource{fn accessor_work_demand(&self,access:semio_framework_value_native_source::NativeSourceAccess)->Result<u64,ValueError>{Ok(if matches!(access,semio_framework_value_native_source::NativeSourceAccess::RecordName(_)){2}else{1})}fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<crate::owned::tree::NativeTreeKind>{Some(crate::owned::tree::NativeTreeKind::Object)}fn record_key(&self,index:usize)->Result<NativeRecordKey<'_>,ValueError>{if index!=0{return Err(invalid())}Ok(match self.ordinal{Some(n)=>NativeRecordKey::Ordinal(n),None=>NativeRecordKey::Name(&self.name)})}}
impl crate::retirement::RetireOwned for KeySource{type Retirement=<String as crate::retirement::RetireOwned>::Retirement;fn retirement(self)->Self::Retirement{self.name.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.name.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=*fuel);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
#[test]fn actual_native_schema_matcher_visits_flattened_original_names_in_bounded_turns(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];for case in law["cases"].as_array().unwrap(){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let maximum=s["maximumTurns"].as_u64().unwrap();let input=KeySource{name:case["key"].as_str().unwrap_or("").into(),ordinal:case["ordinal"].as_u64().map(|n|n as u16)};let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(input,&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w|*w.1,|w,p,work,_,_|post(w.0,w.1,p,work))};let(mut cursor,heap)=crate::observe_retirement_allocations(||NativeRecordMatcher::<KeySource>::new(root_schema,4,NativeSchemaKeySource::Record(0)));assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);for _ in 0..maximum{if cursor.result().is_some(){break}let d=cursor.demands(source.borrow(),4096,fuel).unwrap();let g=RetainedCloneGrant{maximum_items:1,..bank};for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,denied,crate::source_fixture::WorkLoan::new(&fuel,fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(source.borrow(),native,4096,maximum,denied)}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,g,crate::source_fixture::WorkLoan::new(&fuel,fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(source.borrow(),native,4096,maximum,g)}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}let result=cursor.result().unwrap();let actual=match result{NativeFieldMatch::Missing=>serde_json::json!({"kind":"missing","field":null}),NativeFieldMatch::Field(field)=>serde_json::json!({"kind":"field","field":field}),NativeFieldMatch::Ambiguous=>serde_json::json!({"kind":"ambiguous","field":null})};assert_eq!(actual,serde_json::json!({"kind":case["kind"],"field":case["field"]}));cursor.begin_close();let mut actual=None;for _ in 0..maximum{if cursor.terminal_is_empty()&&actual.is_none(){break}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::close_step(&mut actual,RetainedCloneGrant{maximum_items:1,..bank},fuel,cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a)));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}assert!(cursor.terminal_is_empty());drop(cursor);for _ in 0..maximum{if source.terminal_is_empty()&&actual.is_none(){break}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::close_step(&mut actual,RetainedCloneGrant{maximum_items:1,..bank},fuel,source.next_close_demand(4096),source.next_close_work_demand(4096),|g,a|source.close_step(g,a)));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}assert!(source.terminal_is_empty());}}
